// Generates one real HTML file per page (so each URL has its own title, description and
// social preview, and returns 200 on GitHub Pages), plus sitemap.xml and robots.txt.
// Runs automatically from vite.config.js; the generated files are git-ignored
// (when you add a new top-level page here, add its folder to .gitignore too).
import { mkdirSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { PRODUCTS } from '../src/data.js'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const BRAND = 'SipSonic Software Solutions'

// path: URL path relative to the site root ('' = home). page: id read by src/main.jsx.
export function pageList() {
  return [
    {
      path: '',
      page: 'home',
      title: `${BRAND} | AI Agents, AI Dashboards, Web & Mobile Apps`,
      description: 'SipSonic Software Solutions builds AI agents, AI-powered dashboards, web apps, mobile apps and custom software for businesses. Smart software, built fast.',
    },
    {
      path: 'services/',
      page: 'services',
      title: `Services | ${BRAND}`,
      description: 'AI agents, AI-powered dashboards, web apps, mobile apps and custom business software, built fast at a reasonable price. See what we build and how we work.',
    },
    {
      path: 'products/',
      page: 'products',
      title: `Products | ${BRAND}`,
      description: 'Real software products SipSonic has built and delivered for customers. Watch the demos.',
    },
    ...PRODUCTS.map((p) => ({
      path: `products/${p.slug}/`,
      page: 'product',
      slug: p.slug,
      title: `${p.name}: ${p.category} | ${BRAND}`,
      description: p.text,
      image: p.poster || undefined,
    })),
    {
      path: 'pricing/',
      page: 'pricing',
      title: `Pricing | ${BRAND}`,
      description: 'Affordable, transparent pricing for websites, web apps, mobile apps, AI agents and AI dashboards. Free consultation and a fixed quote within 24 hours.',
    },
    {
      path: 'reviews/',
      page: 'reviews',
      title: `Client Reviews | ${BRAND}`,
      description: 'What businesses say about working with SipSonic Software Solutions on their AI, web and mobile software.',
    },
    {
      path: 'about/',
      page: 'about',
      title: `About | ${BRAND}`,
      description: 'Meet the team behind SipSonic Software Solutions, an AI-powered software company from Sri Lanka.',
    },
    {
      path: 'contact/',
      page: 'contact',
      title: `Contact | ${BRAND}`,
      description: 'Tell us about your project. Free consultation, reply within 24 hours. Call, WhatsApp or email SipSonic.',
    },
    { path: 'privacy/', page: 'privacy', title: `Privacy Policy | ${BRAND}`, description: `How ${BRAND} collects and uses your information.` },
    { path: 'terms/', page: 'terms', title: `Terms of Service | ${BRAND}`, description: `Terms for using the ${BRAND} website and services.` },
    { path: '404.html', page: 'notfound', title: `Page not found | ${BRAND}`, description: 'This page does not exist.', noindex: true },
  ]
}

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;')

function html(p, siteUrl) {
  const url = siteUrl + p.path
  const image = siteUrl + (p.image || 'og-image.png')
  const data = `data-page="${p.page}"${p.slug ? ` data-slug="${esc(p.slug)}"` : ''}`
  return `<!doctype html>
<!-- Generated by scripts/pages.mjs. Do not edit; change the page list there instead. -->
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>${esc(p.title)}</title>
    <meta name="description" content="${esc(p.description)}" />
    ${p.noindex ? '<meta name="robots" content="noindex" />' : `<link rel="canonical" href="${url}" />`}
    <meta name="theme-color" content="#FFFFFF" />
    <link rel="icon" type="image/svg+xml" href="/favicon.svg" />
    <meta property="og:site_name" content="${BRAND}" />
    <meta property="og:title" content="${esc(p.title)}" />
    <meta property="og:description" content="${esc(p.description)}" />
    <meta property="og:type" content="website" />
    <meta property="og:url" content="${url}" />
    <meta property="og:image" content="${image}" />
    <meta name="twitter:card" content="summary_large_image" />
    <meta name="twitter:title" content="${esc(p.title)}" />
    <meta name="twitter:description" content="${esc(p.description)}" />
    <meta name="twitter:image" content="${image}" />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />
  </head>
  <body>
    <div id="root" ${data}></div>
    <script type="module" src="/src/main.jsx"></script>
  </body>
</html>
`
}

// Writes the HTML files and returns the Rollup input map for vite.config.js.
export function generatePages(siteUrl) {
  const input = {}
  const pages = pageList()
  for (const p of pages) {
    const file = p.path.endsWith('.html') ? p.path : `${p.path}index.html`
    const abs = resolve(ROOT, file)
    mkdirSync(dirname(abs), { recursive: true })
    writeFileSync(abs, html(p, siteUrl))
    input[p.path.replace(/\/$/, '').replace(/\.html$/, '').replace(/\//g, '-') || 'main'] = abs
  }

  const today = new Date().toISOString().slice(0, 10)
  const urls = pages
    .filter((p) => !p.noindex)
    .map((p) => `  <url><loc>${siteUrl}${p.path}</loc><lastmod>${today}</lastmod></url>`)
    .join('\n')
  writeFileSync(
    resolve(ROOT, 'public/sitemap.xml'),
    `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls}\n</urlset>\n`
  )
  writeFileSync(resolve(ROOT, 'public/robots.txt'), `User-agent: *\nAllow: /\n\nSitemap: ${siteUrl}sitemap.xml\n`)
  return input
}
